const l = new Ledger();
l.deposit('A', 1000, 't1');
l.deposit('B', 1000, 't2');
l.withdraw('A', 100, 't3');
l.withdraw('B', 10, 't4');

const l = new Ledger();
l.deposit('A', 1000, 't1');
l.withdraw('A', 100, 't2');
const es = l.entries('A');
const w = es.filter(e => e.kind === 'withdrawal');

test.assert:
expect(es).toHaveLength(3);
expect(w).toHaveLength(1);
expect(w[0].amount).toBe(100);
expect(es.filter(e => e.kind !== 'deposit' && e.kind !== 'withdrawal').map(e => e.amount)).toEqual([1]);

